HERO_ATK = 3
POTION = 8
TRAP_DMG = 1
SIGHT = 10
COUNTER = False
REGEN = 5
FIXED_SPEED = False
# ------------------------------------------------------------------------------------------


STATS = {"r": (3, 1, 100), "g": (6, 2, 60), "s": (4, 2, 150)}  # hp, attack, speed
DIRS = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
ORDER = "UDLR"


class Monster:
    def __init__(self, ident, kind, y, x):
        self.id = ident
        self.kind = kind
        self.y = y
        self.x = x
        self.hp, self.atk, speed = STATS[kind]
        self.speed = 100 if FIXED_SPEED else speed
        self.energy = 0


